package cn.tbforum.security;
import cn.tbforum.repo.Repositories.Users; import io.jsonwebtoken.JwtException; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.context.annotation.*; import org.springframework.security.authentication.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.crypto.bcrypt.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.cors.*; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List;
@Configuration @EnableWebSecurity public class SecurityConfig {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean SecurityFilterChain security(HttpSecurity http, JwtService jwt, Users users) throws Exception { return http.cors(c->{}).csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/api/forums/**","/api/posts/**","/api/tags/**","/api/users/**","/api/notifications/**","/ws/**","/actuator/health","/error","/","/index.html","/assets/**","/uploads/**").permitAll().anyRequest().authenticated()).addFilterBefore(new JwtFilter(jwt,users),UsernamePasswordAuthenticationFilter.class).build(); }
 @Bean org.springframework.web.servlet.config.annotation.WebMvcConfigurer staticResources(){return new org.springframework.web.servlet.config.annotation.WebMvcConfigurer(){@Override public void addResourceHandlers(org.springframework.web.servlet.config.annotation.ResourceHandlerRegistry r){r.addResourceHandler("/uploads/**").addResourceLocations("file:uploads/");}};}
 @Bean CorsConfigurationSource corsConfigurationSource(){var c=new CorsConfiguration();c.setAllowedOriginPatterns(List.of("http://localhost:*","http://127.0.0.1:*","http://192.168.*:*","http://10.*:*","http://172.16.*:*"));c.setAllowedMethods(List.of("GET","POST","PATCH","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type"));var source=new UrlBasedCorsConfigurationSource();source.registerCorsConfiguration("/**",c);return source;}
 static class JwtFilter extends OncePerRequestFilter { final JwtService jwt; final Users users; JwtFilter(JwtService j,Users u){jwt=j;users=u;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException { String h=r.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer "))try{var u=users.findByUsername(jwt.subject(h.substring(7))).orElse(null);if(u!=null){var a=new UsernamePasswordAuthenticationToken(u.username,null,java.util.List.of(new SimpleGrantedAuthority("ROLE_"+u.role)));SecurityContextHolder.getContext().setAuthentication(a);}}catch(JwtException ignored){} c.doFilter(r,s); } }
}
